package promote

import (
	"context"
	"fmt"
	"strconv"

	"github.com/openartifact/openartifact/internal/database/models"
)

// rpmPromoter promotes rpm packages. A bundle item is the .rpm blob; every live
// rpm_packages row of the source that references it is copied into the
// destination with all its metadata (the header offsets and rpm_extra the
// repodata generator reads included). The repodata is generated by the rpm
// worker, so the destination's rpm_repos row is created when missing and
// flagged stale, and the result asks for a refresh.
type rpmPromoter struct{}

func (rpmPromoter) Format() string { return "rpm" }

// rpmDefaultBaseArch is the base architecture the upload path gives the
// rpm_repos row it creates.
const rpmDefaultBaseArch = "x86_64"

// rpmRow is a live source rpm_packages row holding the item's content.
type rpmRow struct {
	candidate

	pkgVersion, release string
	epoch               int
	arch, filename      string
}

// quarantineKeys are the identifiers the package download checks for quarantine.
func (r *rpmRow) quarantineKeys() []string {
	keys := []string{r.id, r.filename}

	if r.filename != "" {
		keys = append(keys, "Packages/"+r.filename)
	}

	return nonEmpty(keys...)
}

// rpmDisplayVersion renders [epoch:]version[-release].
func rpmDisplayVersion(epoch int, version, release string) string {
	if release != "" {
		version += "-" + release
	}

	if epoch != 0 {
		version = strconv.Itoa(epoch) + ":" + version
	}

	return version
}

const rpmSourceQuery = `SELECT rp.id::text, rp.name, rp.version, rp.release, rp.epoch, rp.arch,
	       COALESCE(rp.filename, ''), COALESCE(rp.license, ''), b.size_bytes
	  FROM rpm_packages rp JOIN blobs b ON b.id = rp.blob_id
	 WHERE rp.repository_id = $1 AND rp.deleted_at IS NULL AND b.sha256 = $2
	 ORDER BY rp.created_at, rp.id`

// rpmDestinationQuery returns the id, content digest and size of every live destination row
// with the package's NEVRA, or with its file name: the file name carries no
// epoch and the download resolves by file name only, so one name must not
// stand for two contents.
const rpmDestinationQuery = `SELECT d.id::text, db.sha256, db.size_bytes, d.name, d.version, d.release, d.epoch, COALESCE(d.filename, '')
	  FROM rpm_packages d JOIN blobs db ON db.id = d.blob_id
	 WHERE d.repository_id = $1 AND d.deleted_at IS NULL
	   AND ((d.name = $2 AND d.version = $3 AND d.release = $4 AND d.epoch = $5 AND d.arch = $6)
	     OR ($7::text <> '' AND d.filename = $7::text))`

// rpmCopyQuery copies every metadata column of a package row; id, the
// timestamps and the soft-delete markers take their
// defaults.
const rpmCopyQuery = `INSERT INTO rpm_packages (repository_id, blob_id, name, version, release, epoch, arch,
	       summary, description, license, url, vendor, group_name, packager, source_rpm, build_host, build_time,
	       filename, package_size, installed_size, archive_size, header_start, header_end, rpm_extra)
	SELECT $1::uuid, s.blob_id, s.name, s.version, s.release, s.epoch, s.arch,
	       s.summary, s.description, s.license, s.url, s.vendor, s.group_name, s.packager, s.source_rpm, s.build_host, s.build_time,
	       s.filename, s.package_size, s.installed_size, s.archive_size, s.header_start, s.header_end, s.rpm_extra
	  FROM rpm_packages s WHERE s.id = $2::uuid AND s.deleted_at IS NULL`

// rpmMarkStaleQuery flags the destination's repodata stale, creating the
// rpm_repos row the metadata worker needs (as the upload path does) when the
// repository has none yet. Signing key columns stay unset.
const rpmMarkStaleQuery = `WITH marked AS (
	  UPDATE rpm_repos SET metadata_stale = true WHERE repository_id = $1::uuid RETURNING id
	)
	INSERT INTO rpm_repos (repository_id, base_arch)
	SELECT $1::uuid, $2 WHERE NOT EXISTS (SELECT 1 FROM marked)
	ON CONFLICT (repository_id, base_arch) DO UPDATE SET metadata_stale = true`

// Promote implements Promoter.
func (p rpmPromoter) Promote(ctx context.Context, tx Tx, req Request) (*Result, error) {
	rows, err := p.sources(ctx, tx, req)
	if err != nil {
		return nil, err
	}

	res := &Result{}

	for _, row := range narrowRows(rows, func(r *rpmRow) candidate { return r.candidate }, req.Path) {
		if err := p.promoteRow(ctx, tx, req, row, res); err != nil {
			return nil, err
		}
	}

	if len(res.Copied) > 0 {
		if _, err := tx.ExecContext(ctx, rpmMarkStaleQuery, req.Dst.ID, rpmDefaultBaseArch); err != nil {
			return nil, fmt.Errorf("mark target rpm repodata stale: %w", err)
		}

		res.Regen = append(res.Regen, Regen{Kind: RegenRPM, RepoID: req.Dst.ID})
	}

	return res, nil
}

// sources returns the live source rows with the item's content.
func (rpmPromoter) sources(ctx context.Context, tx Tx, req Request) ([]*rpmRow, error) {
	rows, err := tx.QueryContext(ctx, rpmSourceQuery, req.Src.ID, req.SHA256)
	if err != nil {
		return nil, fmt.Errorf("select rpm source rows: %w", err)
	}

	defer func() { _ = rows.Close() }()

	var out []*rpmRow

	for rows.Next() {
		var (
			r       rpmRow
			license string
		)

		if err := rows.Scan(&r.id, &r.name, &r.pkgVersion, &r.release, &r.epoch, &r.arch,
			&r.filename, &license, &r.size); err != nil {
			return nil, fmt.Errorf("scan rpm source row: %w", err)
		}

		r.version = rpmDisplayVersion(r.epoch, r.pkgVersion, r.release)
		r.idents = nonEmpty(r.filename, "Packages/"+r.filename, r.id)
		r.licenses = nonEmpty(license)

		out = append(out, &r)
	}

	if err := rows.Err(); err != nil {
		return nil, fmt.Errorf("read rpm source rows: %w", err)
	}

	if len(out) == 0 {
		return nil, ErrItemNotFound
	}

	return out, nil
}

// promoteRow copies one source row unless the destination already holds it.
func (p rpmPromoter) promoteRow(ctx context.Context, tx Tx, req Request, row *rpmRow, res *Result) error {
	art := Artifact{Name: row.name, Version: row.version, Path: row.filename, SHA256: req.SHA256, Size: row.size}
	res.QuarantineKeys = append(res.QuarantineKeys, row.quarantineKeys()...)

	dest, err := p.destination(ctx, tx, req, row)
	if err != nil {
		return err
	}

	if err := dest.replace(ctx, tx, req, models.TrashKindRPM, "rpm", row.name, row.version, res); err != nil {
		return err
	}

	switch {
	case dest.same:
		res.Existing = append(res.Existing, art)
	default:
		if err := p.copyRow(ctx, tx, req, row); err != nil {
			return err
		}

		res.Copied = append(res.Copied, art)
		res.Usage.Bytes += row.size
		res.Usage.Artifacts++
		res.Licenses = append(res.Licenses, row.licenses...)
	}

	return nil
}

// destination collects what the destination holds for the source row: rows
// with the same content (same) and rows with another content at the package's
// NEVRA or file name (differing).
func (rpmPromoter) destination(ctx context.Context, tx Tx, req Request, row *rpmRow) (*destCollisions, error) {
	rows, err := tx.QueryContext(ctx, rpmDestinationQuery,
		req.Dst.ID, row.name, row.pkgVersion, row.release, row.epoch, row.arch, row.filename)
	if err != nil {
		return nil, fmt.Errorf("look up rpm package in the target: %w", err)
	}

	defer func() { _ = rows.Close() }()

	c := &destCollisions{}

	for rows.Next() {
		var (
			d            destRow
			version, rel string
			epoch        int
		)

		if err := rows.Scan(&d.id, &d.sha, &d.size, &d.name, &version, &rel, &epoch, &d.path); err != nil {
			return nil, fmt.Errorf("scan rpm target row: %w", err)
		}

		if d.sha != req.SHA256 {
			d.version = rpmDisplayVersion(epoch, version, rel)
			c.differing = append(c.differing, d)
		} else {
			c.same = true
		}
	}

	if err := rows.Err(); err != nil {
		return nil, fmt.Errorf("read rpm target rows: %w", err)
	}

	return c, nil
}

// copyRow writes the package row into the destination.
func (rpmPromoter) copyRow(ctx context.Context, tx Tx, req Request, row *rpmRow) error {
	res, err := tx.ExecContext(ctx, rpmCopyQuery, req.Dst.ID, row.id)
	if err != nil {
		return fmt.Errorf("copy rpm package row into the target: %w", err)
	}

	if n, err := res.RowsAffected(); err == nil && n == 0 {
		return fmt.Errorf("copy rpm package row into the target: %w", ErrItemNotFound)
	}

	return nil
}
